const mongoose = require('mongoose');
const QuestionBank = require('./server/models/QuestionBank.js');

// Connect to database
mongoose.connect(process.env.MONGO_URI || 'mongodb://localhost:27017/openlearn-hub')
  .then(async () => {
    console.log('Connected to MongoDB');
    
    // Check all question categories
    const categories = await QuestionBank.distinct('category');
    console.log('Available categories in QuestionBank:', categories);
    
    // Count questions per category
    for (const category of categories) {
      const count = await QuestionBank.countDocuments({ category });
      console.log(`Category "${category}": ${count} questions`);
    }
    
    // Check a sample question
    const sampleQuestion = await QuestionBank.findOne();
    console.log('\nSample question structure:', JSON.stringify(sampleQuestion, null, 2));
    
    mongoose.connection.close();
  })
  .catch(err => {
    console.error('MongoDB connection error:', err);
  });
